/* accessibility-fixes.js - Minified */
class AccessibilityFixes{constructor(){this.init()}init(){"undefined"!=typeof Featurable?this.fixFeaturableAccessibility():window.addEventListener("load",()=>{setTimeout(()=>this.fixFeaturableAccessibility(),1e3)}),this.fixVideoAccessibility(),this.fixSliderFocusability()}fixFeaturableAccessibility(){document.querySelectorAll('[class*="carousel__btn--left"]').forEach(e=>{e.getAttribute("aria-label")||e.setAttribute("aria-label","Ver reseña anterior")}),document.querySelectorAll('[class*="carousel__btn--right"]').forEach(e=>{e.getAttribute("aria-label")||e.setAttribute("aria-label","Ver reseña siguiente")}),document.querySelectorAll('[class*="review__reviewer-img"]').forEach(e=>{if(!e.getAttribute("alt")){const t=e.closest('[class*="review"]'),i=t?.querySelector('[class*="reviewer-name"]')?.textContent?.trim();e.setAttribute("alt",i?`Foto de ${i}`:"Foto de perfil del cliente")}});const e=new MutationObserver(()=>{this.fixFeaturableAccessibility()}),t=document.querySelector('[data-featurable-group="review card"]');t&&e.observe(t.parentElement,{childList:!0,subtree:!0})}fixVideoAccessibility(){document.querySelectorAll(".persistent-video-element, .hero-background-video").forEach(e=>{e.setAttribute("aria-hidden","true"),e.setAttribute("role","presentation")})}fixSliderFocusability(){const e=()=>{document.querySelectorAll('[class*="slick-slide"]').forEach(e=>{const t="true"===e.getAttribute("aria-hidden");e.querySelectorAll("button, a, input, select, textarea, [tabindex]").forEach(e=>{t?e.setAttribute("tabindex","-1"):e.hasAttribute("tabindex")&&"-1"!==e.getAttribute("tabindex")||e.setAttribute("tabindex","0")})})};e();const t=new MutationObserver(e);document.querySelectorAll('[class*="slick-slider"]').forEach(e=>{t.observe(e,{attributes:!0,subtree:!0,attributeFilter:["aria-hidden"]})})}}"loading"===document.readyState?document.addEventListener("DOMContentLoaded",()=>new AccessibilityFixes):new AccessibilityFixes;